fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            // For n >= 4, we only need to add 1 if n is odd, 0 if n is even.
            // That is exactly n % 2 for positive n.
            if n >= 4 {
                n % 2
            } else {
                // For 2 and 3, we need to bring n up to 4.
                4 - n
            }
        })
        .collect()
}

